#!/usr/bin/env node
'use strict';

/**
 * Strict RFC-001 M2 -> SHACL projection.
 *
 * `projectShacl(document)` is a pure projection and returns generated bytes.
 * Filesystem access is isolated to the explicit CLI input/output adapter.
 */

const fs = require('node:fs');
const path = require('node:path');
const yaml = require('js-yaml');
const {
  FACT_IDENTITY,
  FACT_VERSION,
  MONEY,
  NS,
  PATTERNS,
  PROVENANCE_FIELDS,
  ProjectionInputError,
  QUANTITY,
  TEMPORAL_FIELDS,
  addRdfList,
  addTriple,
  attributeProjection,
  blankNode,
  literal,
  namedNode,
  rolePredicate,
  serializeTurtle,
  shortDigest,
  sortedEntries,
  sortedValues,
  validateDocument,
  VERSION_OF,
} = require('./lib/typed-projection-common.cjs');
const {
  effectivePatternInjectedAttributeUses,
} = require('./lib/pattern-injected-fields.cjs');
const {
  assertDirectSparqlSelect,
  directSparqlStaticResultPath,
} = require('./lib/direct-sparql-select.cjs');

const SIMPLE_XONE_RE = /^sh:xone\(\s*([A-Za-z][A-Za-z0-9]*(?:\s*,\s*[A-Za-z][A-Za-z0-9]*)+)\s*\)$/u;
const CUSTOM_CONSTRAINT_COMPONENT =
  'https://axiolune.ai/conformance/m2/0.3.0/components/CustomConstraintComponent';
const EXACT_VERSION_REFERENCE =
  'https://axiolune.ai/ontology/meta/core/constraints/ExactVersionReference';
const LOGICAL_REFERENCE =
  'https://axiolune.ai/ontology/meta/core/constraints/LogicalReference';
const REFERENCE_MODE_CONSTRAINTS = new Set([
  EXACT_VERSION_REFERENCE,
  LOGICAL_REFERENCE,
]);
const SHACL_COMPONENT = Object.freeze({
  class: `${NS.SH}ClassConstraintComponent`,
  datatype: `${NS.SH}DatatypeConstraintComponent`,
  in: `${NS.SH}InConstraintComponent`,
  maxCount: `${NS.SH}MaxCountConstraintComponent`,
  minCount: `${NS.SH}MinCountConstraintComponent`,
  node: `${NS.SH}NodeConstraintComponent`,
  nodeKind: `${NS.SH}NodeKindConstraintComponent`,
  not: `${NS.SH}NotConstraintComponent`,
  pattern: `${NS.SH}PatternConstraintComponent`,
  sparql: `${NS.SH}SPARQLConstraintComponent`,
  xone: `${NS.SH}XoneConstraintComponent`,
});

function manifestSeverity(value) {
  const severity = { Error: 'violation', Warning: 'warning', Info: 'info' }[value];
  if (!severity) throw new Error(`unsupported constraint severity ${String(value)}`);
  return severity;
}

function recordConstraint(inventory, value) {
  if (!inventory) return;
  inventory.push(Object.freeze({
    originKind: value.originKind || 'generatedConstraint',
    originRef: value.originRef,
    targetRef: value.targetRef,
    ...(value.path ? { pathKind: value.pathKind || 'iri', path: value.path } : {}),
    component: value.component,
    severity: value.severity || 'violation',
    generatedOrAuthored: value.generatedOrAuthored || 'generated',
  }));
}

function integerLiteral(value) {
  return literal(String(value), namedNode(`${NS.XSD}integer`));
}

function addCardinality(quads, propertyShape, minCount, maxCount) {
  // sh:minCount 0 is tautological and cannot produce the mandatory negative
  // violation for a public constraint instance.  Omit it from both RDF and
  // inventory; maxCount 0 remains meaningful and must still be emitted.
  if (minCount !== undefined && minCount !== null && minCount > 0) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}minCount`), integerLiteral(minCount));
  }
  if (maxCount !== undefined && maxCount !== null) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}maxCount`), integerLiteral(maxCount));
  }
}

function propertyShapeIri(ownerIri, pathIri, scope = 'property') {
  return `${ownerIri}/shape/${scope}/${shortDigest(pathIri)}`;
}

function addPropertyShape(quads, ownerShape, ownerIri, pathIri, options = {}) {
  const propertyShape = namedNode(propertyShapeIri(ownerIri, pathIri, options.scope));
  addTriple(quads, ownerShape, namedNode(`${NS.SH}property`), propertyShape);
  // `sh:property` is the wrapper that delegates validation to the property
  // shape.  A failed inner constraint reports that inner component (for
  // example MinCount), not a separately executable PropertyConstraint
  // instance, so it is intentionally absent from the release inventory.
  addTriple(quads, propertyShape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}PropertyShape`));
  addTriple(quads, propertyShape, namedNode(`${NS.SH}path`), namedNode(pathIri));
  addCardinality(quads, propertyShape, options.minCount, options.maxCount);
  if (options.datatype) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}datatype`), namedNode(options.datatype));
  }
  if (options.classIri) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}class`), namedNode(options.classIri));
  }
  if (options.nodeKind) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}nodeKind`), namedNode(options.nodeKind));
  }
  if (options.node) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}node`), namedNode(options.node));
  }
  if (options.pattern) {
    addTriple(quads, propertyShape, namedNode(`${NS.SH}pattern`), literal(options.pattern));
  }
  if (options.inTerms) {
    const list = addRdfList(
      quads,
      options.inTerms,
      `sh-in\0${ownerIri}\0${pathIri}\0${options.scope || 'property'}`,
    );
    addTriple(quads, propertyShape, namedNode(`${NS.SH}in`), list);
  }
  const context = {
    originRef: options.originRef || pathIri,
    targetRef: options.targetRef || ownerIri,
    path: pathIri,
  };
  for (const [field, component] of [
    ['minCount', SHACL_COMPONENT.minCount],
    ['maxCount', SHACL_COMPONENT.maxCount],
    ['datatype', SHACL_COMPONENT.datatype],
    ['classIri', SHACL_COMPONENT.class],
    ['nodeKind', SHACL_COMPONENT.nodeKind],
    ['node', SHACL_COMPONENT.node],
    ['pattern', SHACL_COMPONENT.pattern],
    ['inTerms', SHACL_COMPONENT.in],
  ]) {
    const present = options[field] !== undefined && options[field] !== null;
    const executable = field !== 'minCount' || options[field] > 0;
    if (present && executable) {
      recordConstraint(options.inventory, {
        ...context,
        ...(options.componentContexts?.[field] || {}),
        component,
      });
    }
  }
  return propertyShape;
}

function projectionError(pathValue, message) {
  throw new ProjectionInputError(pathValue, message);
}

function parseSimpleXone(expression, pathValue) {
  const match = SIMPLE_XONE_RE.exec(expression.trim());
  if (!match) {
    projectionError(
      pathValue,
      'unsupported SHACL expression; expected exactly sh:xone(branchOne,branchTwo,...)',
    );
  }
  const branches = match[1].split(',').map((value) => value.trim());
  if (new Set(branches).size !== branches.length) {
    projectionError(pathValue, 'sh:xone branch names must be unique');
  }
  return branches;
}

function candidateName(model, iri) {
  return model.symbols.get(iri)?.element.localName
    || iri.slice(Math.max(iri.lastIndexOf('/'), iri.lastIndexOf('#')) + 1);
}

function resolveXoneBranch(model, target, branch, pathValue) {
  const candidates = [];
  for (const use of target.element.attributeUses || []) {
    if (candidateName(model, use.attribute) === branch) {
      candidates.push({
        kind: 'attribute',
        pathIri: use.attribute,
        minCount: use.minCount,
        maxCount: use.maxCount,
      });
    }
  }
  for (const role of target.element.participantRoles || []) {
    if (role.id === branch) {
      candidates.push({
        kind: 'participantRole',
        pathIri: rolePredicate(target.element.iri, role.id),
        minCount: role.minCount,
        maxCount: role.maxCount,
      });
    }
  }
  for (const use of model.domain.relationUses) {
    if (use.subjectType === target.element.iri
        && candidateName(model, use.relation) === branch) {
      candidates.push({
        kind: 'relationUse',
        pathIri: use.relation,
        minCount: use.outboundCardinality?.minCount,
        maxCount: use.outboundCardinality?.maxCount,
      });
    }
  }
  const unique = [...new Map(candidates.map((candidate) => [candidate.pathIri, candidate])).values()];
  if (unique.length !== 1) {
    projectionError(
      pathValue,
      unique.length === 0
        ? `sh:xone branch ${branch} does not resolve to a local AttributeUse, ParticipantRole, or RelationUse`
        : `sh:xone branch ${branch} is ambiguous`,
    );
  }
  const selected = unique[0];
  if ((selected.minCount ?? 0) !== 0 || selected.maxCount !== 1) {
    projectionError(
      pathValue,
      `sh:xone branch ${branch} must be authored as optional 0..1 before the xone makes it exactly one`,
    );
  }
  return selected;
}

function addSimpleXoneConstraint(quads, model, constraint, localNameValue, inventory) {
  const pathValue = `domain.constraints.${localNameValue}.expression.expression`;
  const branches = parseSimpleXone(constraint.expression.expression, pathValue);
  if (!constraint.targetElement) {
    projectionError(`domain.constraints.${localNameValue}.targetElement`, 'is required for SHACL projection');
  }
  const target = model.symbols.get(constraint.targetElement);
  if (!target || !['objectTypes', 'associationTypes'].includes(target.kind)) {
    projectionError(
      `domain.constraints.${localNameValue}.targetElement`,
      'must resolve to a local ObjectTypeDefinition or AssociationTypeDefinition',
    );
  }
  const bindings = model.domain.constraintBindings.filter(
    (binding) => binding.constraintRef === constraint.iri,
  );
  if (bindings.length !== 1 || bindings[0].targetElement !== constraint.targetElement) {
    projectionError(
      `domain.constraints.${localNameValue}`,
      'SHACL constraint must have exactly one matching top-level ConstraintBinding',
    );
  }

  const constraintShape = namedNode(`${constraint.iri}/shape`);
  addTriple(quads, constraintShape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
  // Bind the authored entry shape directly.  A `targetShape sh:node
  // constraintShape` wrapper changes the portable top-level result component
  // to sh:NodeConstraintComponent (and some engines suppress the nested
  // sh:XoneConstraintComponent result entirely), so such a wrapper cannot
  // satisfy the manifest's exact sourceConstraintComponent contract.
  addTriple(
    quads,
    constraintShape,
    namedNode(`${NS.SH}targetClass`),
    namedNode(target.element.iri),
  );
  addTriple(quads, constraintShape, namedNode(`${NS.SH}message`), literal(constraint.message));
  const severity = {
    Error: 'Violation',
    Warning: 'Warning',
    Info: 'Info',
  }[constraint.severity];
  if (!severity) {
    projectionError(
      `domain.constraints.${localNameValue}.severity`,
      'must be Error, Warning, or Info for SHACL projection',
    );
  }
  addTriple(
    quads,
    constraintShape,
    namedNode(`${NS.SH}severity`),
    namedNode(`${NS.SH}${severity}`),
  );

  const branchShapes = branches.map((branch, index) => {
    const selected = resolveXoneBranch(model, target, branch, pathValue);
    const branchShape = namedNode(
      `${constraint.iri}/shape/xone/${index}-${shortDigest(`${branch}\0${selected.pathIri}`)}`,
    );
    addTriple(quads, branchShape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
    addPropertyShape(
      quads,
      branchShape,
      constraint.iri,
      selected.pathIri,
      {
        minCount: 1,
        maxCount: 1,
        scope: `xone-${index}-${branch}`,
        // These cardinalities are structural operands of sh:xone, not
        // independently targetable public constraint instances.  Both
        // rdf-validate-shacl and pySHACL report the enclosing Xone component,
        // not these nested Min/Max components, so do not invent manifest rows
        // that no exact execution result can satisfy.
      },
    );
    return branchShape;
  });
  const list = addRdfList(
    quads,
    branchShapes,
    `sh-xone\0${constraint.iri}\0${branches.join('\0')}`,
  );
  addTriple(quads, constraintShape, namedNode(`${NS.SH}xone`), list);
  recordConstraint(inventory, {
    originKind: 'constraintDefinition',
    originRef: constraint.iri,
    targetRef: target.element.iri,
    component: SHACL_COMPONENT.xone,
    severity: manifestSeverity(constraint.severity),
    generatedOrAuthored: 'authored',
  });
}

function addDirectSparqlConstraint(quads, model, constraint, localNameValue, inventory) {
  const pathValue = `domain.constraints.${localNameValue}.expression.expression`;
  const select = assertDirectSparqlSelect(constraint.expression.expression, pathValue);
  const staticResultPath = directSparqlStaticResultPath(select, pathValue);
  if (!constraint.targetElement) {
    projectionError(`domain.constraints.${localNameValue}.targetElement`, 'is required for SPARQL projection');
  }
  const target = model.symbols.get(constraint.targetElement);
  if (!target || !['objectTypes', 'associationTypes'].includes(target.kind)) {
    projectionError(
      `domain.constraints.${localNameValue}.targetElement`,
      'must resolve to a local ObjectTypeDefinition or AssociationTypeDefinition',
    );
  }
  const bindings = model.domain.constraintBindings.filter(
    (binding) => binding.constraintRef === constraint.iri,
  );
  if (bindings.length !== 1 || bindings[0].targetElement !== constraint.targetElement) {
    projectionError(
      `domain.constraints.${localNameValue}`,
      'SPARQL constraint must have exactly one matching top-level ConstraintBinding',
    );
  }

  const severity = {
    Error: 'Violation',
    Warning: 'Warning',
    Info: 'Info',
  }[constraint.severity];
  if (!severity) {
    projectionError(
      `domain.constraints.${localNameValue}.severity`,
      'must be Error, Warning, or Info for SPARQL projection',
    );
  }

  const constraintShape = namedNode(`${constraint.iri}/shape`);
  const sparqlConstraint = namedNode(`${constraint.iri}/shape/sparql`);
  addTriple(quads, constraintShape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
  // As with authored sh:xone, bind the authored SPARQL entry shape directly so
  // the portable result component is sh:SPARQLConstraintComponent rather than
  // an engine-dependent sh:NodeConstraintComponent wrapper.
  addTriple(
    quads,
    constraintShape,
    namedNode(`${NS.SH}targetClass`),
    namedNode(target.element.iri),
  );
  addTriple(quads, constraintShape, namedNode(`${NS.SH}message`), literal(constraint.message));
  addTriple(
    quads,
    constraintShape,
    namedNode(`${NS.SH}severity`),
    namedNode(`${NS.SH}${severity}`),
  );
  addTriple(quads, constraintShape, namedNode(`${NS.SH}sparql`), sparqlConstraint);
  addTriple(
    quads,
    sparqlConstraint,
    namedNode(`${NS.RDF}type`),
    namedNode(`${NS.SH}SPARQLConstraint`),
  );
  addTriple(quads, sparqlConstraint, namedNode(`${NS.SH}message`), literal(constraint.message));
  addTriple(quads, sparqlConstraint, namedNode(`${NS.SH}select`), literal(select));
  recordConstraint(inventory, {
    originKind: 'constraintDefinition',
    originRef: constraint.iri,
    targetRef: target.element.iri,
    ...(staticResultPath ? { path: staticResultPath } : {}),
    component: SHACL_COMPONENT.sparql,
    severity: manifestSeverity(constraint.severity),
    generatedOrAuthored: 'authored',
  });
}

function addExecutableConstraints(quads, model, inventory) {
  for (const [localNameValue, constraint] of sortedEntries(model.domain.constraints)) {
    if (constraint.expression.language === 'SHACL') {
      addSimpleXoneConstraint(quads, model, constraint, localNameValue, inventory);
    } else if (constraint.expression.language === 'SPARQL') {
      addDirectSparqlConstraint(quads, model, constraint, localNameValue, inventory);
    }
  }
}

function addStructuredValueShapes(quads, model, inventory) {
  const projections = [...model.symbols.values()]
    .filter((symbol) => symbol.kind === 'attributeTypes')
    .map((symbol) => attributeProjection(model, symbol.element));
  const needsMoney = projections.some((projection) => projection.range === MONEY.classIri);
  const needsQuantity = projections.some((projection) => projection.range === QUANTITY.classIri);

  if (needsMoney) {
    const shape = namedNode(`${MONEY.classIri}Shape`);
    addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
    addTriple(quads, shape, namedNode(`${NS.SH}targetClass`), namedNode(MONEY.classIri));
    addPropertyShape(quads, shape, MONEY.classIri, MONEY.amount, {
      minCount: 1, maxCount: 1, datatype: `${NS.XSD}decimal`, scope: 'component',
      inventory,
    });
    addPropertyShape(quads, shape, MONEY.classIri, MONEY.currency, {
      minCount: 1,
      maxCount: 1,
      datatype: `${NS.XSD}string`,
      pattern: '^[A-Z]{3}$',
      scope: 'component',
      inventory,
    });
    addPropertyShape(quads, shape, MONEY.classIri, MONEY.scale, {
      minCount: 1, maxCount: 1, datatype: `${NS.XSD}integer`, scope: 'component',
      inventory,
    });
  }

  if (needsQuantity) {
    const shape = namedNode(`${QUANTITY.classIri}Shape`);
    addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
    addTriple(quads, shape, namedNode(`${NS.SH}targetClass`), namedNode(QUANTITY.classIri));
    addPropertyShape(quads, shape, QUANTITY.classIri, QUANTITY.value, {
      minCount: 1, maxCount: 1, datatype: `${NS.XSD}decimal`, scope: 'component',
      inventory,
    });
    addPropertyShape(quads, shape, QUANTITY.classIri, QUANTITY.unit, {
      minCount: 1,
      maxCount: 1,
      datatype: `${NS.XSD}string`,
      pattern: '^[A-Za-z][A-Za-z0-9+.-]*:[^\\s]+$',
      scope: 'component',
      inventory,
    });
    addPropertyShape(quads, shape, QUANTITY.classIri, QUANTITY.precision, {
      minCount: 0, maxCount: 1, datatype: `${NS.XSD}integer`, scope: 'component',
      inventory,
    });
    addPropertyShape(quads, shape, QUANTITY.classIri, QUANTITY.rounding, {
      minCount: 1,
      maxCount: 1,
      datatype: `${NS.XSD}string`,
      inTerms: ['floor', 'ceiling', 'half-up', 'half-even'].map((value) => literal(value)),
      scope: 'component',
      inventory,
    });
  }
}

function addValidIntervalConstraint(quads, shape, element, inventory) {
  const constraint = blankNode(
    `temporal_valid_interval_${
      shortDigest(`${element.iri}\0${TEMPORAL_FIELDS.validFrom}\0${TEMPORAL_FIELDS.validTo}`)
    }`,
  );
  const select = [
    'SELECT $this ?path',
    'WHERE {',
    `  $this <${TEMPORAL_FIELDS.validFrom}> ?validFrom ;`,
    `        <${TEMPORAL_FIELDS.validTo}> ?validTo .`,
    `  BIND(<${TEMPORAL_FIELDS.validTo}> AS ?path)`,
    `  FILTER (STRDT(STR(?validFrom), <${NS.XSD}dateTime>)`
      + ` >= STRDT(STR(?validTo), <${NS.XSD}dateTime>))`,
    '}',
  ].join('\n');
  addTriple(quads, shape, namedNode(`${NS.SH}sparql`), constraint);
  addTriple(
    quads,
    constraint,
    namedNode(`${NS.RDF}type`),
    namedNode(`${NS.SH}SPARQLConstraint`),
  );
  addTriple(
    quads,
    constraint,
    namedNode(`${NS.SH}message`),
    literal('validFrom must occur strictly before validTo'),
  );
  addTriple(quads, constraint, namedNode(`${NS.SH}select`), literal(select));
  recordConstraint(inventory, {
    originRef: element.iri,
    targetRef: element.iri,
    path: TEMPORAL_FIELDS.validTo,
    component: SHACL_COMPONENT.sparql,
  });
}

function addPatternTierOne(quads, shape, element, inventory) {
  const patterns = new Set((element.patternBindings || []).map((binding) => binding.pattern));
  for (const use of effectivePatternInjectedAttributeUses(element)) {
    addPropertyShape(quads, shape, element.iri, use.attribute, {
      ...(Object.hasOwn(use, 'minCount') ? { minCount: use.minCount } : {}),
      ...(Object.hasOwn(use, 'maxCount') ? { maxCount: use.maxCount } : {}),
      ...(use.maxCount === 0 ? {} : { datatype: use.datatype }),
      scope: use.scope,
      inventory,
    });
  }
  if (patterns.has(PATTERNS.temporal)) {
    addValidIntervalConstraint(quads, shape, element, inventory);
  }
}

function addAttributeUse(quads, model, shape, owner, use, inventory) {
  const symbol = model.symbols.get(use.attribute);
  if (!symbol) {
    addPropertyShape(quads, shape, owner.iri, use.attribute, {
      minCount: use.minCount,
      maxCount: use.maxCount,
      scope: 'imported-attribute',
      inventory,
    });
    return;
  }
  if (symbol.kind !== 'attributeTypes') {
    throw new Error(`${owner.iri}.attributeUses: ${use.attribute} is not an AttributeTypeDefinition`);
  }
  const definition = symbol.element;
  const projection = attributeProjection(model, definition);
  const options = {
    minCount: use.minCount ?? definition.defaultCardinality?.minCount,
    maxCount: use.maxCount ?? definition.defaultCardinality?.maxCount,
    pattern: definition.pattern,
    scope: 'attribute',
    inventory,
  };
  if (projection.kind === 'object') {
    options.classIri = projection.range;
    options.nodeKind = `${NS.SH}BlankNodeOrIRI`;
    if (projection.range === MONEY.classIri || projection.range === QUANTITY.classIri) {
      options.node = `${projection.range}Shape`;
    }
    if (projection.codeList) {
      options.nodeKind = `${NS.SH}IRI`;
      options.inTerms = sortedValues(projection.codeList.values)
        .map((member) => namedNode(member.iri));
    }
  } else {
    options.datatype = projection.range;
  }
  addPropertyShape(quads, shape, owner.iri, use.attribute, options);
}

function addAttributeDefinitionShape(quads, model, definition, inventory) {
  const projection = attributeProjection(model, definition);
  const shape = namedNode(`${definition.iri}Shape`);
  addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}PropertyShape`));
  addTriple(quads, shape, namedNode(`${NS.SH}path`), namedNode(definition.iri));
  addTriple(quads, shape, namedNode(`${NS.SH}targetSubjectsOf`), namedNode(definition.iri));
  if (definition.pattern) {
    addTriple(quads, shape, namedNode(`${NS.SH}pattern`), literal(definition.pattern));
    recordConstraint(inventory, {
      originRef: definition.iri,
      targetRef: definition.iri,
      path: definition.iri,
      component: SHACL_COMPONENT.pattern,
    });
  }
  if (projection.kind === 'object') {
    addTriple(quads, shape, namedNode(`${NS.SH}class`), namedNode(projection.range));
    recordConstraint(inventory, {
      originRef: definition.iri,
      targetRef: definition.iri,
      path: definition.iri,
      component: SHACL_COMPONENT.class,
    });
    addTriple(
      quads,
      shape,
      namedNode(`${NS.SH}nodeKind`),
      namedNode(projection.codeList ? `${NS.SH}IRI` : `${NS.SH}BlankNodeOrIRI`),
    );
    recordConstraint(inventory, {
      originRef: definition.iri,
      targetRef: definition.iri,
      path: definition.iri,
      component: SHACL_COMPONENT.nodeKind,
    });
    if (projection.range === MONEY.classIri || projection.range === QUANTITY.classIri) {
      addTriple(
        quads,
        shape,
        namedNode(`${NS.SH}node`),
        namedNode(`${projection.range}Shape`),
      );
      recordConstraint(inventory, {
        originRef: definition.iri,
        targetRef: definition.iri,
        path: definition.iri,
        component: SHACL_COMPONENT.node,
      });
    }
    if (projection.codeList) {
      const members = sortedValues(projection.codeList.values)
        .map((member) => namedNode(member.iri));
      const list = addRdfList(
        quads,
        members,
        `attribute-code-list\0${definition.iri}`,
      );
      addTriple(quads, shape, namedNode(`${NS.SH}in`), list);
      recordConstraint(inventory, {
        originRef: definition.iri,
        targetRef: definition.iri,
        path: definition.iri,
        component: SHACL_COMPONENT.in,
      });
    }
  } else {
    addTriple(quads, shape, namedNode(`${NS.SH}datatype`), namedNode(projection.range));
    recordConstraint(inventory, {
      originRef: definition.iri,
      targetRef: definition.iri,
      path: definition.iri,
      component: SHACL_COMPONENT.datatype,
    });
  }
}

function addTypeShape(quads, model, element, inventory) {
  const shape = namedNode(`${element.iri}Shape`);
  addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
  addTriple(quads, shape, namedNode(`${NS.SH}targetClass`), namedNode(element.iri));
  addTriple(quads, shape, namedNode(`${NS.SH}name`), literal(element.label));
  addTriple(quads, shape, namedNode(`${NS.SH}description`), literal(element.definition));
  for (const use of element.attributeUses || []) {
    addAttributeUse(quads, model, shape, element, use, inventory);
  }
  addPatternTierOne(quads, shape, element, inventory);
  return shape;
}

function addCodeListShape(quads, codeList, inventory) {
  const shape = namedNode(`${codeList.iri}Shape`);
  addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
  addTriple(quads, shape, namedNode(`${NS.SH}targetClass`), namedNode(codeList.iri));
  addTriple(quads, shape, namedNode(`${NS.SH}nodeKind`), namedNode(`${NS.SH}IRI`));
  recordConstraint(inventory, {
    originRef: codeList.iri,
    targetRef: codeList.iri,
    component: SHACL_COMPONENT.nodeKind,
  });
  const members = sortedValues(codeList.values).map((member) => namedNode(member.iri));
  const list = addRdfList(quads, members, `code-list-shape\0${codeList.iri}`);
  addTriple(quads, shape, namedNode(`${NS.SH}in`), list);
  recordConstraint(inventory, {
    originRef: codeList.iri,
    targetRef: codeList.iri,
    component: SHACL_COMPONENT.in,
  });
}

function logicalIdentityClassIri(typeIri) {
  return `${typeIri}/LogicalIdentity`;
}

function singleReferenceConstraint(candidates, expectedTarget, pathValue) {
  const matches = (candidates || []).filter(
    (candidate) => REFERENCE_MODE_CONSTRAINTS.has(candidate.constraintRef),
  );
  if (matches.length > 1) {
    projectionError(pathValue, 'expected at most one ExactVersionReference/LogicalReference');
  }
  if (matches.length === 0) return null;
  if (matches[0].targetElement !== undefined
      && matches[0].targetElement !== expectedTarget) {
    projectionError(
      `${pathValue}.targetElement`,
      `must equal the constrained path ${expectedTarget}`,
    );
  }
  return matches[0];
}

function participantRoleReferenceConstraint(model, association, role) {
  const pathIri = rolePredicate(association.iri, role.id);
  return singleReferenceConstraint(
    model.domain.constraintBindings.filter((binding) => binding.targetElement === pathIri),
    pathIri,
    `${association.iri}.participantRoles.${role.id}.referenceMode`,
  );
}

function relationUseReferenceConstraint(use) {
  return singleReferenceConstraint(
    use.constraints,
    use.relation,
    `${use.subjectType}.relationUses.${use.relation}.referenceMode`,
  );
}

function addDirectShapeConstraint(quads, shape, predicate, object, inventory, context) {
  addTriple(quads, shape, namedNode(predicate), object);
  recordConstraint(inventory, context);
}

function addReferenceTargetShape(
  quads,
  model,
  expectedType,
  constraintRef,
  inventory,
  referenceShapes,
) {
  const mode = constraintRef === EXACT_VERSION_REFERENCE ? 'exact' : 'logical';
  const key = `${mode}\0${expectedType}`;
  const shapeIri = `${expectedType}/shape/reference/${mode}`;
  if (referenceShapes.has(key)) return shapeIri;
  referenceShapes.add(key);

  const localTarget = model.symbols.get(expectedType);
  if (mode === 'logical' && localTarget?.element.abstract === true) {
    projectionError(
      expectedType,
      'LogicalReference cannot target an abstract type without a logical-identity companion',
    );
  }

  const shape = namedNode(shapeIri);
  addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
  addDirectShapeConstraint(
    quads,
    shape,
    `${NS.SH}nodeKind`,
    namedNode(`${NS.SH}IRI`),
    inventory,
    {
      originRef: constraintRef,
      targetRef: shapeIri,
      component: SHACL_COMPONENT.nodeKind,
    },
  );

  if (mode === 'exact') {
    addDirectShapeConstraint(
      quads,
      shape,
      `${NS.SH}class`,
      namedNode(expectedType),
      inventory,
      {
        originRef: expectedType,
        targetRef: shapeIri,
        component: SHACL_COMPONENT.class,
      },
    );
    const factVersionContractIri = `${shapeIri}/fact-version-contract`;
    const factVersionContract = namedNode(factVersionContractIri);
    addDirectShapeConstraint(
      quads,
      shape,
      `${NS.SH}node`,
      factVersionContract,
      inventory,
      {
        originRef: FACT_VERSION,
        targetRef: shapeIri,
        component: SHACL_COMPONENT.node,
      },
    );
    addTriple(
      quads,
      factVersionContract,
      namedNode(`${NS.RDF}type`),
      namedNode(`${NS.SH}NodeShape`),
    );
    addDirectShapeConstraint(
      quads,
      factVersionContract,
      `${NS.SH}class`,
      namedNode(FACT_VERSION),
      inventory,
      {
        originRef: FACT_VERSION,
        targetRef: factVersionContractIri,
        component: SHACL_COMPONENT.class,
      },
    );
    addPropertyShape(quads, factVersionContract, factVersionContractIri, VERSION_OF, {
      minCount: 1,
      maxCount: 1,
      classIri: FACT_IDENTITY,
      nodeKind: `${NS.SH}IRI`,
      scope: 'reference-exact-version-of',
      inventory,
      originRef: VERSION_OF,
      targetRef: factVersionContractIri,
    });
  } else {
    const companion = logicalIdentityClassIri(expectedType);
    addDirectShapeConstraint(
      quads,
      shape,
      `${NS.SH}class`,
      namedNode(companion),
      inventory,
      {
        originRef: companion,
        targetRef: shapeIri,
        component: SHACL_COMPONENT.class,
      },
    );
    const factIdentityContractIri = `${shapeIri}/fact-identity-contract`;
    const factIdentityContract = namedNode(factIdentityContractIri);
    addDirectShapeConstraint(
      quads,
      shape,
      `${NS.SH}node`,
      factIdentityContract,
      inventory,
      {
        originRef: FACT_IDENTITY,
        targetRef: shapeIri,
        component: SHACL_COMPONENT.node,
      },
    );
    addTriple(
      quads,
      factIdentityContract,
      namedNode(`${NS.RDF}type`),
      namedNode(`${NS.SH}NodeShape`),
    );
    addDirectShapeConstraint(
      quads,
      factIdentityContract,
      `${NS.SH}class`,
      namedNode(FACT_IDENTITY),
      inventory,
      {
        originRef: FACT_IDENTITY,
        targetRef: factIdentityContractIri,
        component: SHACL_COMPONENT.class,
      },
    );
    const notFactVersion = namedNode(`${factIdentityContractIri}/not-fact-version`);
    addDirectShapeConstraint(
      quads,
      factIdentityContract,
      `${NS.SH}not`,
      notFactVersion,
      inventory,
      {
        originRef: FACT_VERSION,
        targetRef: factIdentityContractIri,
        component: SHACL_COMPONENT.not,
      },
    );
    addTriple(
      quads,
      notFactVersion,
      namedNode(`${NS.RDF}type`),
      namedNode(`${NS.SH}NodeShape`),
    );
    addDirectShapeConstraint(
      quads,
      notFactVersion,
      `${NS.SH}class`,
      namedNode(FACT_VERSION),
      inventory,
      {
        originRef: FACT_VERSION,
        targetRef: notFactVersion.value,
        component: SHACL_COMPONENT.class,
      },
    );
    addPropertyShape(quads, factIdentityContract, factIdentityContractIri, VERSION_OF, {
      maxCount: 0,
      scope: 'reference-logical-version-of',
      inventory,
      originRef: VERSION_OF,
      targetRef: factIdentityContractIri,
    });
  }
  return shapeIri;
}

function addRelationUseShape(quads, model, use, inventory, referenceShapes) {
  const key = `${use.relation}\0${use.subjectType}\0${use.objectType}`;
  const shapeIri = `${use.subjectType}/shape/relation-use/${shortDigest(key)}`;
  const shape = namedNode(shapeIri);
  addTriple(quads, shape, namedNode(`${NS.RDF}type`), namedNode(`${NS.SH}NodeShape`));
  addTriple(quads, shape, namedNode(`${NS.SH}targetClass`), namedNode(use.subjectType));
  const referenceConstraint = relationUseReferenceConstraint(use);
  const options = {
    nodeKind: `${NS.SH}IRI`,
    minCount: use.outboundCardinality?.minCount,
    maxCount: use.outboundCardinality?.maxCount,
    scope: 'relation-use',
    inventory,
    originRef: use.relation,
    targetRef: use.subjectType,
  };
  if (referenceConstraint) {
    options.node = addReferenceTargetShape(
      quads,
      model,
      use.objectType,
      referenceConstraint.constraintRef,
      inventory,
      referenceShapes,
    );
    options.componentContexts = {
      node: {
        originKind: 'constraintDefinition',
        originRef: referenceConstraint.constraintRef,
        severity: 'violation',
        generatedOrAuthored: 'authored',
      },
    };
  } else {
    options.classIri = use.objectType;
  }
  addPropertyShape(quads, shape, shapeIri, use.relation, options);
}

function inventoryContextKey(value) {
  const pathPresent = Object.hasOwn(value, 'pathKind') || Object.hasOwn(value, 'path');
  return [
    value.originKind,
    value.originRef,
    value.targetRef,
    pathPresent ? '1' : '0',
    pathPresent ? value.pathKind : '',
    pathPresent ? value.path : '',
    value.component,
  ].join('\0');
}

function sortAndDedupeInventory(inventory) {
  const byContext = new Map();
  for (const entry of inventory) {
    const key = inventoryContextKey(entry);
    const previous = byContext.get(key);
    if (previous) {
      if (previous.severity !== entry.severity
          || previous.generatedOrAuthored !== entry.generatedOrAuthored) {
        throw new Error(`constraint inventory context has conflicting metadata: ${key}`);
      }
      continue;
    }
    byContext.set(key, entry);
  }
  return [...byContext.values()].sort((left, right) => Buffer.compare(
    Buffer.from(inventoryContextKey(left), 'utf8'),
    Buffer.from(inventoryContextKey(right), 'utf8'),
  ));
}

function addAuthoredBindingContexts(model, inventory) {
  const localConstraints = new Map(
    Object.values(model.domain.constraints).map((constraint) => [constraint.iri, constraint]),
  );
  const representedBindings = new Set(
    inventory
      .filter((entry) => entry.originKind === 'constraintDefinition')
      .map((entry) => {
        // Reference-mode constraints are authored against a relation/role path,
        // while direct node constraints (including SPARQL constraints that bind
        // a static result path) are authored against their target element.
        const bindingTarget = REFERENCE_MODE_CONSTRAINTS.has(entry.originRef)
          ? entry.path
          : entry.targetRef;
        return `${entry.originRef}\0${bindingTarget}`;
      }),
  );

  for (const binding of model.domain.constraintBindings) {
    const bindingKey = `${binding.constraintRef}\0${binding.targetElement}`;
    if (representedBindings.has(bindingKey)) continue;
    const constraint = localConstraints.get(binding.constraintRef);
    if (constraint) {
      if (constraint.expression.language === 'SHACL'
          || constraint.expression.language === 'SPARQL') {
        throw new Error(
          `authored ${constraint.expression.language} binding was not compiled: ${bindingKey}`,
        );
      }
      recordConstraint(inventory, {
        originKind: 'constraintDefinition',
        originRef: binding.constraintRef,
        targetRef: binding.targetElement,
        component: CUSTOM_CONSTRAINT_COMPONENT,
        severity: manifestSeverity(constraint.severity),
        generatedOrAuthored: 'authored',
      });
      representedBindings.add(bindingKey);
      continue;
    }
    if (!REFERENCE_MODE_CONSTRAINTS.has(binding.constraintRef)) {
      throw new Error(`unknown imported ConstraintBinding constraintRef: ${binding.constraintRef}`);
    }
    throw new Error(`authored reference-mode binding was not compiled: ${bindingKey}`);
  }

  const missing = model.domain.constraintBindings.filter((binding) => (
    !representedBindings.has(`${binding.constraintRef}\0${binding.targetElement}`)
  ));
  if (missing.length > 0) {
    throw new Error(`constraint inventory omitted ${missing.length} authored binding context(s)`);
  }
}

async function projectShaclArtifacts(document) {
  const model = validateDocument(document);
  const quads = [];
  const inventory = [];
  const referenceShapes = new Set();
  addStructuredValueShapes(quads, model, inventory);
  for (const [, attribute] of sortedEntries(model.domain.attributeTypes)) {
    addAttributeDefinitionShape(quads, model, attribute, inventory);
  }

  for (const [, objectType] of sortedEntries(model.domain.objectTypes)) {
    addTypeShape(quads, model, objectType, inventory);
  }
  for (const [, association] of sortedEntries(model.domain.associationTypes)) {
    const shape = addTypeShape(quads, model, association, inventory);
    association.participantRoles
      .slice()
      .sort((a, b) => Buffer.compare(Buffer.from(a.id, 'utf8'), Buffer.from(b.id, 'utf8')))
      .forEach((role) => {
        const pathIri = rolePredicate(association.iri, role.id);
        const referenceConstraint = participantRoleReferenceConstraint(
          model,
          association,
          role,
        );
        const options = {
          minCount: role.minCount,
          maxCount: role.maxCount,
          nodeKind: `${NS.SH}IRI`,
          scope: `participant-role-${role.id}`,
          inventory,
          originRef: pathIri,
          targetRef: association.iri,
        };
        if (referenceConstraint) {
          options.node = addReferenceTargetShape(
            quads,
            model,
            role.range,
            referenceConstraint.constraintRef,
            inventory,
            referenceShapes,
          );
          options.componentContexts = {
            node: {
              originKind: 'constraintDefinition',
              originRef: referenceConstraint.constraintRef,
              severity: 'violation',
              generatedOrAuthored: 'authored',
            },
          };
        } else {
          options.classIri = role.range;
        }
        addPropertyShape(
          quads,
          shape,
          association.iri,
          pathIri,
          options,
        );
      });
  }
  for (const [, codeList] of sortedEntries(model.domain.codeLists)) {
    addCodeListShape(quads, codeList, inventory);
  }
  model.domain.relationUses
    .slice()
    .sort((a, b) => {
      const left = `${a.relation}\0${a.subjectType}\0${a.objectType}`;
      const right = `${b.relation}\0${b.subjectType}\0${b.objectType}`;
      return Buffer.compare(Buffer.from(left, 'utf8'), Buffer.from(right, 'utf8'));
    })
    .forEach((use) => addRelationUseShape(
      quads,
      model,
      use,
      inventory,
      referenceShapes,
    ));
  addExecutableConstraints(quads, model, inventory);
  addAuthoredBindingContexts(model, inventory);

  const bytes = await serializeTurtle(quads, {
    rdf: NS.RDF,
    sh: NS.SH,
    xsd: NS.XSD,
    [model.module.preferredPrefix]: model.module.baseIri,
  });
  return {
    bytes,
    contexts: sortAndDedupeInventory(inventory),
  };
}

async function projectShacl(document) {
  return (await projectShaclArtifacts(document)).bytes;
}

async function projectShaclWithInventory(document) {
  return projectShaclArtifacts(document);
}

async function runCli(argv = process.argv.slice(2)) {
  if (argv.length !== 2) {
    throw new Error('Usage: node generate-m2-shacl.cjs <module.yaml> <output.ttl|->');
  }
  const [inputFile, outputFile] = argv;
  const resolvedInput = path.resolve(inputFile);
  if (!fs.existsSync(resolvedInput)) throw new Error(`${inputFile}: not found`);
  const resolvedOutput = outputFile === '-' ? null : path.resolve(outputFile);
  const pathKey = (value) => (
    process.platform === 'win32' ? value.toLowerCase() : value
  );
  const aliasesInput = resolvedOutput !== null && (
    pathKey(resolvedOutput) === pathKey(resolvedInput)
    || (fs.existsSync(resolvedOutput)
      && fs.statSync(resolvedOutput).dev === fs.statSync(resolvedInput).dev
      && fs.statSync(resolvedOutput).ino === fs.statSync(resolvedInput).ino)
  );
  if (aliasesInput) {
    throw new Error('output path must not overwrite the source module');
  }
  const document = yaml.load(fs.readFileSync(resolvedInput, 'utf8'));
  const bytes = await projectShacl(document);
  if (outputFile === '-') {
    process.stdout.write(bytes);
  } else {
    fs.mkdirSync(path.dirname(resolvedOutput), { recursive: true });
    fs.writeFileSync(resolvedOutput, bytes);
  }
  return bytes;
}

if (require.main === module) {
  runCli().catch((error) => {
    console.error(`${error.code ? `${error.code}: ` : ''}${error.message}`);
    process.exitCode = 1;
  });
}

module.exports = {
  CUSTOM_CONSTRAINT_COMPONENT,
  EXACT_VERSION_REFERENCE,
  LOGICAL_REFERENCE,
  SHACL_COMPONENT,
  addReferenceTargetShape,
  inventoryContextKey,
  logicalIdentityClassIri,
  projectShacl,
  projectShaclWithInventory,
  runCli,
};
